});

test('addLine validates qty', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(
    addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty: -1 }),
